{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "The objective of this systematic review and meta-analysis was to evaluate the pooled efficacy and safety of high-dose versus low-dose thromboprophylaxis for VTE in hospitalized patients with COVID-19.",
      "reason": "The review objective is explicitly stated in the manuscript introduction/methods context."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "The objective of this systematic review and meta-analysis was to evaluate the pooled efficacy and safety of high-dose versus low-dose thromboprophylaxis for VTE in hospitalized patients with COVID-19. The primary efficacy outcome was the occurrence of any symptomatic or incidental VTE. Secondary efficacy outcomes were all-cause mortality, acute myocardial infarction, acute ischemic stroke, acute peripheral arterial ischemic events, symptomatic or incidental deep vein thrombosis (DVT), and symptomatic or incidental pulmonary embolism (PE). The primary safety outcome was major bleeding as defined by the authors, while the secondary safety outcomes were clinically relevant nonmajor bleeding and heparin-induced thrombocytopenia.",
      "reason": "The planned comparison is stated (high-dose vs low-dose thromboprophylaxis), and outcomes are listed, but the evidence does not show a fully specified PICO/PICO-variant framework (e.g., explicit comparator details framed as PICO structure)."
    }
  ],
  "confidence": 78
}

